// ---------------------------------------------------------------------------------------------- runtime
// Everything below is the same for every schema: the query AST, the immutable builder, the in-memory
// executor (Table) and the remote executor (connect). docs/QUERY.md describes the algorithm; the Python
// client (history.py) implements the same one.

export type Op = "eq" | "ne" | "lt" | "le" | "gt" | "ge" | "in" | "between" | "isNull";
export type AggregateFn = "count" | "sum" | "avg" | "min" | "max";
export type ScopeName = "myBee" | "myFlower" | "mine";
export type Dir = "asc" | "desc";
export type FieldType = "int" | "float" | "bool" | "str" | "json";

/** One condition: `field op value`. */
export interface Condition { readonly field: string; readonly op: Op; readonly value: Json }
/** One aggregate: fn over field (count without a field counts rows), named `as`. */
export interface Aggregate { readonly fn: AggregateFn; readonly field?: string; readonly as: string }
export interface Order { readonly field: string; readonly dir: Dir }
/** The language-neutral query: what every executor runs (docs/QUERY.md). */
export interface Ast {
  readonly from: EntityName;
  readonly scope?: ScopeName;
  readonly where?: readonly Condition[];
  readonly groupBy?: readonly string[];
  readonly aggregates?: readonly Aggregate[];
  readonly select?: readonly string[];
  readonly orderBy?: readonly Order[];
  readonly limit?: number;
  readonly offset?: number;
}
/** What the server answers a query with. */
export interface Page { readonly rows: readonly unknown[]; readonly truncated?: boolean }

export interface FieldInfo { readonly name: string; readonly type: FieldType; readonly nullable: boolean }
export interface EntityInfo {
  readonly record: string;
  readonly key: readonly string[];
  readonly sortedBy: string | null;
  readonly index: readonly (readonly string[])[];
  readonly cells: readonly string[];
  readonly scopes: { readonly [scope: string]: readonly string[] };
  readonly owner: string | null;
  readonly program: boolean;
  readonly fields: readonly FieldInfo[];
}
export interface TypeInfo { readonly ops: readonly Op[]; readonly order: boolean; readonly group: boolean; readonly aggregates: readonly AggregateFn[] }
export interface Schema { readonly types: { readonly [T in FieldType]: TypeInfo }; readonly entities: { readonly [E in EntityName]: EntityInfo } }

export class QueryError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "QueryError";
  }
}

const fail = (message: string): never => { throw new QueryError(message); };
const AST_KEYS = ["from", "scope", "where", "groupBy", "aggregates", "select", "orderBy", "limit", "offset"];
const NAME = /^[A-Za-z_][A-Za-z0-9_]*$/;
const MAX_IN = 1000;

function deepFreeze<T>(v: T): T {
  if (v !== null && typeof v === "object" && !Object.isFrozen(v)) {
    for (const k of Object.keys(v)) deepFreeze((v as Record<string, unknown>)[k]);
    Object.freeze(v);
  }
  return v;
}

function isJson(v: unknown, depth = 0): boolean {
  if (depth > 64) return false;
  if (v === null || typeof v === "boolean" || typeof v === "string") return true;
  if (typeof v === "number") return Number.isFinite(v);
  if (Array.isArray(v)) return v.every((x) => isJson(x, depth + 1));
  if (typeof v === "object") return Object.keys(v as object).every((k) => isJson((v as Record<string, unknown>)[k], depth + 1));
  return false;
}

/** JSON equality: numbers by value, objects regardless of key order, true is not 1. */
export function jsonEqual(a: unknown, b: unknown): boolean {
  if (a === b) return true;
  if (a === null || b === null || typeof a !== "object" || typeof b !== "object") return false;
  if (Array.isArray(a)) {
    if (!Array.isArray(b) || a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) if (!jsonEqual(a[i], b[i])) return false;
    return true;
  }
  if (Array.isArray(b)) return false;
  const ka = Object.keys(a), kb = Object.keys(b);
  if (ka.length !== kb.length) return false;
  for (const k of ka) if (!Object.prototype.hasOwnProperty.call(b, k) || !jsonEqual((a as Record<string, unknown>)[k], (b as Record<string, unknown>)[k])) return false;
  return true;
}

/** Strings compare by code point (as in SQL with the C collation, and in Python). */
function cmpStr(a: string, b: string): number {
  const n = Math.min(a.length, b.length);
  for (let i = 0; i < n; i++) {
    const x = a.codePointAt(i) as number, y = b.codePointAt(i) as number;
    if (x !== y) return x < y ? -1 : 1;
    if (x > 0xffff) i++;
  }
  return a.length < b.length ? -1 : a.length > b.length ? 1 : 0;
}

function cmpValue(x: unknown, y: unknown): number {
  if (typeof x === "string") return cmpStr(x, y as string);
  if (typeof x === "boolean") return (x ? 1 : 0) - (y ? 1 : 0);
  return (x as number) < (y as number) ? -1 : (x as number) > (y as number) ? 1 : 0;
}

/** Sort rows by `order` (nulls last either way). The sort is stable, so ties keep the rows' order. */
function sortRows<T>(rows: T[], order: readonly Order[]): T[] {
  return rows.sort((a, b) => {
    for (const o of order) {
      const x = (a as Record<string, unknown>)[o.field], y = (b as Record<string, unknown>)[o.field];
      if (x === y) continue;
      if (x === null || x === undefined) return 1;
      if (y === null || y === undefined) return -1;
      const c = cmpValue(x, y);
      if (c !== 0) return o.dir === "desc" ? -c : c;
    }
    return 0;
  });
}

export function entityInfo(name: string): EntityInfo {
  return Object.prototype.hasOwnProperty.call(SCHEMA.entities, name) ? SCHEMA.entities[name as EntityName] : fail(`unknown entity "${name}" (use ${Object.keys(SCHEMA.entities).join(", ")})`);
}

function fieldInfo(e: EntityInfo, name: string, what: string): FieldInfo {
  return e.fields.find((f) => f.name === name) ?? fail(`${what}: unknown field "${name}"`);
}

function checkValue(f: FieldInfo, v: unknown, what: string): void {
  if (v === null || v === undefined) fail(`${what}: the value can't be null (use isNull)`);
  const ok = f.type === "int" ? Number.isSafeInteger(v)
    : f.type === "float" ? typeof v === "number" && Number.isFinite(v)
      : f.type === "bool" ? typeof v === "boolean"
        : f.type === "str" ? typeof v === "string"
          : isJson(v);
  if (!ok) fail(`${what}: ${JSON.stringify(v)?.slice(0, 40)} isn't ${f.type === "int" ? "an int" : f.type === "json" ? "JSON" : `a ${f.type}`}`);
}

/** Check a query against the schema, and fill in the defaults. Throws QueryError. */
export function validate(input: Ast): Ast {
  if (input === null || typeof input !== "object" || Array.isArray(input)) fail("a query must be an object");
  for (const k of Object.keys(input)) if (!AST_KEYS.includes(k)) fail(`unknown query key "${k}"`);
  const e = entityInfo(input.from);
  const out: { -readonly [K in keyof Ast]: Ast[K] } = { from: input.from };
  if (input.scope !== undefined && input.scope !== null) {
    if (!Object.prototype.hasOwnProperty.call(e.scopes, input.scope)) fail(`${input.from} has no scope "${input.scope}" (${Object.keys(e.scopes).join(", ") || "none"})`);
    out.scope = input.scope;
  }
  if (input.where !== undefined) {
    if (!Array.isArray(input.where)) fail("where must be a list");
    out.where = input.where.map((c, i) => {
      const what = `where[${i}]`;
      if (c === null || typeof c !== "object") fail(`${what} must be {field, op, value}`);
      const f = fieldInfo(e, c.field, what);
      if (!SCHEMA.types[f.type].ops.includes(c.op)) fail(`${what}: ${f.name} (${f.type}) takes ${SCHEMA.types[f.type].ops.join(", ")}, not "${c.op}"`);
      if (c.op === "isNull") { if (typeof c.value !== "boolean") fail(`${what}: isNull takes true or false`); }
      else if (c.op === "in") {
        if (!Array.isArray(c.value) || c.value.length === 0 || c.value.length > MAX_IN) fail(`${what}: in takes a list of 1 to ${MAX_IN} values`);
        (c.value as unknown[]).forEach((v) => checkValue(f, v, what));
      } else if (c.op === "between") {
        if (!Array.isArray(c.value) || c.value.length !== 2) fail(`${what}: between takes [low, high]`);
        (c.value as unknown[]).forEach((v) => checkValue(f, v, what));
      } else checkValue(f, c.value, what);
      return { field: f.name, op: c.op, value: c.value };
    });
  }
  const names = new Set<string>();
  if (input.groupBy !== undefined) {
    if (!Array.isArray(input.groupBy)) fail("groupBy must be a list");
    out.groupBy = input.groupBy.map((g) => {
      const f = fieldInfo(e, g, "groupBy");
      if (!SCHEMA.types[f.type].group) fail(`groupBy: ${f.name} (${f.type}) can't be grouped by`);
      if (names.has(f.name)) fail(`groupBy: ${f.name} twice`);
      names.add(f.name);
      return f.name;
    });
  }
  if (input.aggregates !== undefined) {
    if (!Array.isArray(input.aggregates)) fail("aggregates must be a list");
    out.aggregates = input.aggregates.map((a, i) => {
      const what = `aggregates[${i}]`;
      if (a === null || typeof a !== "object" || !["count", "sum", "avg", "min", "max"].includes(a.fn)) fail(`${what}: fn must be count, sum, avg, min or max`);
      let field: string | undefined;
      if (a.field !== undefined && a.field !== null) {
        const f = fieldInfo(e, a.field, what);
        if (!SCHEMA.types[f.type].aggregates.includes(a.fn)) fail(`${what}: ${a.fn} doesn't apply to ${f.name} (${f.type})`);
        field = f.name;
      } else if (a.fn !== "count") fail(`${what}: ${a.fn} needs a field`);
      const as = a.as ?? (field ? `${a.fn}_${field}` : a.fn);
      if (typeof as !== "string" || !NAME.test(as) || as.length > 63) fail(`${what}: "${as}" isn't a valid name`);
      if (names.has(as)) fail(`${what}: the name "${as}" is taken`);
      names.add(as);
      return field === undefined ? { fn: a.fn, as } : { fn: a.fn, field, as };
    });
  }
  const grouped = out.groupBy !== undefined || out.aggregates !== undefined;
  if (input.select !== undefined) {
    if (grouped) fail("select can't be combined with groupBy or aggregates");
    if (!Array.isArray(input.select) || input.select.length === 0) fail("select takes a list of fields");
    const seen = new Set<string>();
    out.select = input.select.map((s) => {
      const f = fieldInfo(e, s, "select");
      if (seen.has(f.name)) fail(`select: ${f.name} twice`);
      seen.add(f.name);
      return f.name;
    });
  }
  if (input.orderBy !== undefined) {
    if (!Array.isArray(input.orderBy)) fail("orderBy must be a list");
    out.orderBy = input.orderBy.map((o, i) => {
      const what = `orderBy[${i}]`;
      if (o === null || typeof o !== "object") fail(`${what} must be {field, dir}`);
      const dir = o.dir ?? "asc";
      if (dir !== "asc" && dir !== "desc") fail(`${what}: dir must be asc or desc`);
      if (grouped) { if (!names.has(o.field)) fail(`${what}: order a grouped query by its group fields or aggregates, not "${o.field}"`); }
      else {
        const f = fieldInfo(e, o.field, what);
        if (!SCHEMA.types[f.type].order) fail(`${what}: ${f.name} (${f.type}) can't be sorted`);
      }
      return { field: o.field, dir };
    });
  }
  for (const k of ["limit", "offset"] as const) {
    const v = input[k];
    if (v === undefined || v === null) continue;
    if (!Number.isSafeInteger(v) || v < 0) fail(`${k} must be a whole number ≥ 0`);
    out[k] = v;
  }
  return deepFreeze(out);
}

// ---------------------------------------------------------------- the builder

type Shape = "records" | "rows";
export type Mode = "sync" | "async";
type Out<M extends Mode, T> = M extends "async" ? Promise<T> : T;
type Field<R> = Extract<keyof R, string>;
type Val<R, K extends keyof R> = Exclude<R[K], null | undefined>;
type Num<R> = { [K in Field<R>]-?: Val<R, K> extends number ? K : never }[Field<R>];
type Grp<R> = { [K in Field<R>]-?: Val<R, K> extends number | string | boolean ? K : never }[Field<R>];
type Base<S extends Shape, Row> = S extends "rows" ? Row : {};
type With<S extends Shape, Row, A extends string, V> = Base<S, Row> & { readonly [P in A]: V };

/** Runs an AST: in memory (a Table) or remotely (connect). */
export interface Runner<M extends Mode> { run(ast: Ast): Out<M, readonly unknown[]> }

const then = <T, U>(x: T | Promise<T>, f: (v: T) => U): U | Promise<U> =>
  x !== null && typeof x === "object" && typeof (x as Promise<T>).then === "function" ? (x as Promise<T>).then(f) : f(x as T);

/**
 * An immutable query. Every method returns a new query; run it with rows(), first() or value(). R is the
 * entity's record type, Row what a result row looks like, M whether results come at once (in memory) or
 * as Promises (remote).
 */
export class Query<R, Row = R, S extends Shape = "records", M extends Mode = "sync"> {
  readonly #ast: Ast;
  readonly #runner: Runner<M>;

  constructor(ast: Ast, runner: Runner<M>) {
    this.#ast = deepFreeze({ ...ast });
    this.#runner = runner;
    Object.freeze(this);
  }

  #next(change: Partial<{ -readonly [K in keyof Ast]: Ast[K] }>): any {
    return new Query({ ...this.#ast, ...change }, this.#runner);
  }

  #where(field: string, op: Op, value: unknown): any {
    return this.#next({ where: [...(this.#ast.where ?? []), { field, op, value: value as Json }] });
  }

  #agg(fn: AggregateFn, field: string | null | undefined, as: string | undefined): any {
    const name = as ?? (field ? `${fn}_${field}` : fn);
    const a: Aggregate = field ? { fn, field, as: name } : { fn, as: name };
    return this.#next({ aggregates: [...(this.#ast.aggregates ?? []), a] });
  }

  eq<K extends Field<R>>(field: K, value: Val<R, K>): Query<R, Row, S, M> { return this.#where(field, "eq", value); }
  ne<K extends Field<R>>(field: K, value: Val<R, K>): Query<R, Row, S, M> { return this.#where(field, "ne", value); }
  lt<K extends Num<R>>(field: K, value: number): Query<R, Row, S, M> { return this.#where(field, "lt", value); }
  le<K extends Num<R>>(field: K, value: number): Query<R, Row, S, M> { return this.#where(field, "le", value); }
  gt<K extends Num<R>>(field: K, value: number): Query<R, Row, S, M> { return this.#where(field, "gt", value); }
  ge<K extends Num<R>>(field: K, value: number): Query<R, Row, S, M> { return this.#where(field, "ge", value); }
  in<K extends Field<R>>(field: K, values: readonly Val<R, K>[]): Query<R, Row, S, M> { return this.#where(field, "in", [...values]); }
  between<K extends Num<R>>(field: K, low: number, high: number): Query<R, Row, S, M> { return this.#where(field, "between", [low, high]); }
  isNull<K extends Field<R>>(field: K): Query<R, Row, S, M> { return this.#where(field, "isNull", true); }
  notNull<K extends Field<R>>(field: K): Query<R, Row, S, M> { return this.#where(field, "isNull", false); }
  /** Rounds low to high, inclusive (entities sorted by round). */
  rounds(low: number, high: number): Query<R, Row, S, M> {
    const by = entityInfo(this.#ast.from).sortedBy;
    return by === "round" ? this.#where(by, "between", [low, high]) : fail(`${this.#ast.from} has no rounds`);
  }

  /** Only your team's bee's turns. */
  myBee(): Query<R, Row, S, M> { return this.#next({ scope: "myBee" }); }
  /** Only the turns at your team's flower. */
  myFlower(): Query<R, Row, S, M> { return this.#next({ scope: "myFlower" }); }
  /** Only your team's records (turns: your bee's or at your flower). */
  mine(): Query<R, Row, S, M> { return this.#next({ scope: "mine" }); }

  /** Only these fields in each row. */
  select<K extends Field<R>>(...fields: K[]): Query<R, Pick<R, K>, S, M> { return this.#next({ select: fields }); }
  /** One row per group, holding the group fields and the aggregates. */
  groupBy<K extends Grp<R>>(...fields: K[]): Query<R, Pick<R, K> & Base<S, Row>, "rows", M> { return this.#next({ groupBy: fields }); }

  count(): Query<R, With<S, Row, "count", number>, "rows", M>;
  count<K extends Field<R>>(field: K): Query<R, With<S, Row, `count_${K}`, number>, "rows", M>;
  count<A extends string>(field: Field<R> | null, as: A): Query<R, With<S, Row, A, number>, "rows", M>;
  count(field?: string | null, as?: string): any { return this.#agg("count", field, as); }
  sum<K extends Num<R>, A extends string = `sum_${K}`>(field: K, as?: A): Query<R, With<S, Row, A, number | null>, "rows", M> { return this.#agg("sum", field, as); }
  avg<K extends Num<R>, A extends string = `avg_${K}`>(field: K, as?: A): Query<R, With<S, Row, A, number | null>, "rows", M> { return this.#agg("avg", field, as); }
  min<K extends Num<R>, A extends string = `min_${K}`>(field: K, as?: A): Query<R, With<S, Row, A, Val<R, K> | null>, "rows", M> { return this.#agg("min", field, as); }
  max<K extends Num<R>, A extends string = `max_${K}`>(field: K, as?: A): Query<R, With<S, Row, A, Val<R, K> | null>, "rows", M> { return this.#agg("max", field, as); }

  /** Sort by a field (or, grouped, an aggregate). Nulls last; ties keep the natural order. */
  orderBy(field: Extract<keyof Row, string>, dir: Dir = "asc"): Query<R, Row, S, M> {
    return this.#next({ orderBy: [...(this.#ast.orderBy ?? []), { field, dir }] });
  }
  limit(n: number): Query<R, Row, S, M> { return this.#next({ limit: n }); }
  offset(n: number): Query<R, Row, S, M> { return this.#next({ offset: n }); }

  /** The query as its JSON AST. */
  ast(): Ast { return this.#ast; }
  /** The result rows (read-only). */
  rows(): Out<M, readonly Row[]> { return this.#runner.run(this.#ast) as Out<M, readonly Row[]>; }
  /** The first result row, or null. */
  first(): Out<M, Row | null> {
    const q: Query<R, Row, S, M> = this.#next({ limit: this.#ast.limit === 0 ? 0 : 1 });
    return then(q.rows() as readonly Row[] | Promise<readonly Row[]>, (rows) => rows[0] ?? null) as Out<M, Row | null>;
  }
  /** The value of a query's only aggregate (without groupBy). */
  value(): Out<M, Row[keyof Row]> {
    const aggs = this.#ast.aggregates ?? [];
    if (aggs.length !== 1 || this.#ast.groupBy) fail("value() needs exactly one aggregate and no groupBy");
    return then(this.rows() as readonly Row[] | Promise<readonly Row[]>, (rows) => (rows[0] as Record<string, unknown>)[aggs[0].as]) as Out<M, Row[keyof Row]>;
  }
}

// ---------------------------------------------------------------- the in-memory executor

interface Cell {
  readonly key: Record<string, unknown>;
  n: number;
  readonly nn: Record<string, number>;
  readonly sum: Record<string, number>;
  readonly min: Record<string, number>;
  readonly max: Record<string, number>;
}

interface Acc { n: number; nn: number; sum: number; min: number; max: number }

const keyOf = (r: Record<string, unknown>, fields: readonly string[]): string => JSON.stringify(fields.map((f) => r[f]));

function compileTest(c: Condition, f: FieldInfo): (r: Record<string, unknown>) => boolean {
  const k = c.field, v = c.value;
  const json = f.type === "json";
  switch (c.op) {
    case "eq": return json ? (r) => r[k] !== null && jsonEqual(r[k], v) : (r) => r[k] !== null && r[k] === v;
    case "ne": return json ? (r) => r[k] !== null && !jsonEqual(r[k], v) : (r) => r[k] !== null && r[k] !== v;
    case "lt": return (r) => r[k] !== null && (r[k] as number) < (v as number);
    case "le": return (r) => r[k] !== null && (r[k] as number) <= (v as number);
    case "gt": return (r) => r[k] !== null && (r[k] as number) > (v as number);
    case "ge": return (r) => r[k] !== null && (r[k] as number) >= (v as number);
    case "between": {
      const [lo, hi] = v as number[];
      return (r) => r[k] !== null && (r[k] as number) >= lo && (r[k] as number) <= hi;
    }
    case "in": {
      const vs = v as Json[];
      if (json) return (r) => r[k] !== null && vs.some((w) => jsonEqual(r[k], w));
      const set = new Set<unknown>(vs);
      return (r) => r[k] !== null && set.has(r[k]);
    }
    case "isNull": return v ? (r) => r[k] === null : (r) => r[k] !== null;
  }
}

const EMPTY: readonly never[] = Object.freeze([]);

/**
 * The in-memory executor over records of one entity, kept in natural order with per-value indexes and
 * running per-cell statistics, all updated incrementally by append(). The records are frozen.
 */
export class Table<R extends object = Record<string, unknown>> {
  readonly entity: EntityName;
  readonly #info: EntityInfo;
  readonly #numeric: readonly string[];
  #records: Record<string, unknown>[] = [];
  #indexes = new Map<string, Map<string, Record<string, unknown>[]>>();
  #cells = new Map<string, Cell>();
  #games = new Set<unknown>();
  #all: readonly R[] | null = null;

  constructor(entity: EntityName, records: readonly unknown[] = []) {
    this.entity = entity;
    this.#info = entityInfo(entity);
    this.#numeric = this.#info.fields.filter((f) => f.type === "int" || f.type === "float").map((f) => f.name);
    this.#reset();
    this.append(records);
    Object.freeze(this);
  }

  /** How many records it holds. */
  get size(): number { return this.#records.length; }

  /** Add records (canonical field names; others are dropped, missing ones are null). Natural order is kept. */
  append(records: readonly unknown[]): void {
    let sorted = true;
    for (const input of records) {
      if (input === null || typeof input !== "object") fail("a record must be an object");
      const r: Record<string, unknown> = {};
      for (const f of this.#info.fields) {
        const v = (input as Record<string, unknown>)[f.name];
        r[f.name] = v === undefined ? null : v;
      }
      deepFreeze(r);
      const last = this.#records[this.#records.length - 1];
      if (last && this.#cmpKey(last, r) > 0) sorted = false;
      this.#records.push(r);
      if (sorted) this.#add(r);
    }
    if (!sorted) {
      const all = this.#records;
      this.#reset();
      this.#records = sortRows(all, this.#info.key.map((field) => ({ field, dir: "asc" as Dir })));
      for (const r of this.#records) this.#add(r);
    }
    this.#all = null;
  }

  /** A query over this table; scopes (myBee, mine, ...) mean `team`. */
  query(team: number | null = null): Query<R> {
    return new Query<R>({ from: this.entity }, { run: (ast: Ast) => this.run(ast, team) });
  }

  #reset(): void {
    this.#records = [];
    this.#indexes = new Map(this.#info.index.map((spec) => [spec.join(","), new Map()]));
    this.#cells = new Map();
    this.#games = new Set();
  }

  #cmpKey(a: Record<string, unknown>, b: Record<string, unknown>): number {
    for (const k of this.#info.key) {
      const x = a[k], y = b[k];
      if (x === y) continue;
      if (x === null) return 1;
      if (y === null) return -1;
      return cmpValue(x, y);
    }
    return 0;
  }

  #add(r: Record<string, unknown>): void {
    if ("game" in r) this.#games.add(r.game);
    for (const spec of this.#info.index) {
      const index = this.#indexes.get(spec.join(",")) as Map<string, Record<string, unknown>[]>;
      const k = keyOf(r, spec);
      const bucket = index.get(k);
      if (bucket) bucket.push(r);
      else index.set(k, [r]);
    }
    const cells = this.#info.cells;
    if (!cells.length) return;
    const ck = keyOf(r, cells);
    let cell = this.#cells.get(ck);
    if (!cell) {
      const key: Record<string, unknown> = {};
      for (const c of cells) key[c] = r[c];
      cell = { key, n: 0, nn: {}, sum: {}, min: {}, max: {} };
      for (const f of this.#info.fields) cell.nn[f.name] = 0;
      for (const f of this.#numeric) { cell.sum[f] = 0; cell.min[f] = Infinity; cell.max[f] = -Infinity; }
      this.#cells.set(ck, cell);
    }
    cell.n++;
    for (const f of this.#info.fields) if (r[f.name] !== null) cell.nn[f.name]++;
    for (const f of this.#numeric) {
      const v = r[f] as number | null;
      if (v === null) continue;
      cell.sum[f] += v;
      if (v < cell.min[f]) cell.min[f] = v;
      if (v > cell.max[f]) cell.max[f] = v;
    }
  }

  /** Run a query (validated first); `team` is what scopes refer to. Returns frozen rows. */
  run(input: Ast, team: number | null = null): readonly any[] {
    const ast = validate(input);
    if (ast.from !== this.entity) fail(`this table holds ${this.entity}, not ${ast.from}`);
    const info = this.#info;
    const where = ast.where ?? [];
    const tests = where.map((c) => compileTest(c, info.fields.find((f) => f.name === c.field) as FieldInfo));
    const scope = ast.scope ? info.scopes[ast.scope] : null;
    const match = (r: Record<string, unknown>): boolean => {
      for (const t of tests) if (!t(r)) return false;
      return scope === null || (team !== null && scope.some((f) => r[f] === team));
    };
    if (ast.groupBy || ast.aggregates) return Object.freeze(this.#aggregate(ast, match, scope, team));
    return this.#select(ast, match, scope, team);
  }

  /** The smallest index bucket the conditions pin down, narrowed to the sortedBy range: [list, lo, hi). */
  #candidates(ast: Ast, scope: readonly string[] | null, team: number | null): [readonly Record<string, unknown>[], number, number] {
    const where = ast.where ?? [];
    const eqOf = (field: string): unknown => {
      if (scope && scope.length === 1 && scope[0] === field) return team === null ? undefined : team;
      const c = where.find((w) => w.field === field && w.op === "eq");
      return c ? c.value : undefined;
    };
    if (scope && team === null) return [EMPTY, 0, 0];
    let list: readonly Record<string, unknown>[] = this.#records;
    for (const spec of this.#info.index) {
      const vals = spec.map(eqOf);
      if (vals.some((v) => v === undefined)) continue;
      const bucket = (this.#indexes.get(spec.join(",")) as Map<string, Record<string, unknown>[]>).get(JSON.stringify(vals)) ?? EMPTY;
      if (bucket.length < list.length) list = bucket;
    }
    let lo = 0, hi = list.length;
    const by = this.#info.sortedBy;
    if (by && this.#games.size <= 1) {
      let low = -Infinity, high = Infinity, lowStrict = false, highStrict = false;
      const above = (v: number, strict: boolean) => { if (v > low || (v === low && strict)) { low = v; lowStrict = strict; } };
      const below = (v: number, strict: boolean) => { if (v < high || (v === high && strict)) { high = v; highStrict = strict; } };
      for (const c of where) {
        if (c.field !== by) continue;
        const v = c.value as number;
        if (c.op === "eq") { above(v, false); below(v, false); }
        else if (c.op === "ge") above(v, false);
        else if (c.op === "gt") above(v, true);
        else if (c.op === "le") below(v, false);
        else if (c.op === "lt") below(v, true);
        else if (c.op === "between") { const [a, b] = c.value as number[]; above(a, false); below(b, false); }
      }
      const bound = (v: number, strict: boolean): number => { // first index whose value is > v (strict) or ≥ v
        let a = 0, b = list.length;
        while (a < b) {
          const m = (a + b) >> 1;
          const x = list[m][by] as number;
          if (x < v || (strict && x === v)) a = m + 1;
          else b = m;
        }
        return a;
      };
      if (low !== -Infinity) lo = bound(low, lowStrict);
      if (high !== Infinity) hi = bound(high, !highStrict);
    }
    return [list, lo, Math.max(lo, hi)];
  }

  #select(ast: Ast, match: (r: Record<string, unknown>) => boolean, scope: readonly string[] | null, team: number | null): readonly any[] {
    const [list, lo, hi] = this.#candidates(ast, scope, team);
    const offset = ast.offset ?? 0, limit = ast.limit ?? Infinity;
    const order = ast.orderBy ?? [];
    const by = this.#info.sortedBy;
    const plain = !(ast.where ?? []).length && scope === null;
    let out: Record<string, unknown>[];
    if (!order.length && plain) {
      if (list === this.#records && lo === 0 && hi === list.length && offset === 0 && limit === Infinity && !ast.select) {
        return this.#all ??= Object.freeze(this.#records.slice()) as readonly R[];
      }
      out = list.slice(lo + offset, Math.min(hi, lo + offset + limit));
    } else if (!order.length) {
      out = [];
      let skip = offset;
      for (let i = lo; i < hi && out.length < limit; i++) {
        const r = list[i];
        if (!match(r)) continue;
        if (skip > 0) { skip--; continue; }
        out.push(r);
      }
    } else if (order.length === 1 && order[0].field === by && order[0].dir === "desc" && this.#games.size <= 1) {
      // Newest first: walk back run by run of equal values, each run in natural order.
      out = [];
      let skip = offset, i = hi;
      while (i > lo && out.length < limit) {
        const v = list[i - 1][by];
        let j = i - 1;
        while (j > lo && list[j - 1][by] === v) j--;
        for (let k = j; k < i && out.length < limit; k++) {
          const r = list[k];
          if (!match(r)) continue;
          if (skip > 0) { skip--; continue; }
          out.push(r);
        }
        i = j;
      }
    } else {
      const rows: Record<string, unknown>[] = [];
      for (let i = lo; i < hi; i++) if (match(list[i])) rows.push(list[i]);
      out = sortRows(rows, order).slice(offset, offset + limit);
    }
    if (ast.select) {
      const sel = ast.select;
      out = out.map((r) => {
        const o: Record<string, unknown> = {};
        for (const f of sel) o[f] = r[f];
        return Object.freeze(o);
      });
    }
    return Object.freeze(out);
  }

  #aggregate(ast: Ast, match: (r: Record<string, unknown>) => boolean, scope: readonly string[] | null, team: number | null): Record<string, unknown>[] {
    const info = this.#info;
    const group = ast.groupBy ?? [];
    const aggs = ast.aggregates ?? [];
    const groups = new Map<string, { vals: Record<string, unknown>; acc: Acc[] }>();
    const groupOf = (r: Record<string, unknown>) => {
      const k = keyOf(r, group);
      let g = groups.get(k);
      if (!g) {
        const vals: Record<string, unknown> = {};
        for (const f of group) vals[f] = r[f];
        g = { vals, acc: aggs.map(() => ({ n: 0, nn: 0, sum: 0, min: Infinity, max: -Infinity })) };
        groups.set(k, g);
      }
      return g;
    };
    const cells = info.cells;
    const inCells = (f: string) => cells.includes(f);
    const viaCells = cells.length > 0 && (ast.where ?? []).every((c) => inCells(c.field)) && (scope ?? []).every(inCells) && group.every(inCells);
    if (viaCells) {
      for (const cell of this.#cells.values()) {
        if (!match(cell.key)) continue;
        const g = groupOf(cell.key);
        aggs.forEach((a, i) => {
          const acc = g.acc[i];
          acc.n += cell.n;
          if (!a.field) return;
          acc.nn += cell.nn[a.field];
          if (a.fn === "count" || !cell.nn[a.field]) return;
          acc.sum += cell.sum[a.field];
          if (cell.min[a.field] < acc.min) acc.min = cell.min[a.field];
          if (cell.max[a.field] > acc.max) acc.max = cell.max[a.field];
        });
      }
    } else {
      const [list, lo, hi] = this.#candidates(ast, scope, team);
      for (let i = lo; i < hi; i++) {
        const r = list[i];
        if (!match(r)) continue;
        const g = groupOf(r);
        aggs.forEach((a, j) => {
          const acc = g.acc[j];
          acc.n++;
          if (!a.field) return;
          const v = r[a.field];
          if (v === null) return;
          acc.nn++;
          if (a.fn === "count") return;
          acc.sum += v as number;
          if ((v as number) < acc.min) acc.min = v as number;
          if ((v as number) > acc.max) acc.max = v as number;
        });
      }
    }
    if (!group.length && !groups.size) groupOf({});
    let rows = [...groups.values()].map(({ vals, acc }) => {
      const row: Record<string, unknown> = { ...vals };
      aggs.forEach((a, i) => {
        const c = acc[i];
        row[a.as] = a.fn === "count" ? (a.field ? c.nn : c.n)
          : c.nn === 0 ? null
            : a.fn === "sum" ? c.sum : a.fn === "avg" ? c.sum / c.nn : a.fn === "min" ? c.min : c.max;
      });
      return Object.freeze(row);
    });
    rows = sortRows(rows, group.map((field) => ({ field, dir: "asc" as Dir })));
    if (ast.orderBy) rows = sortRows(rows, ast.orderBy);
    const offset = ast.offset ?? 0;
    return rows.slice(offset, ast.limit === undefined ? undefined : offset + ast.limit);
  }
}

// ---------------------------------------------------------------- roots: programs, local and remote

/** What programs get as HISTORY: a query per program entity. */
export type ProgramHistory = { readonly [E in ProgramEntity]: Query<Records[E]> };
/** Every entity, queried remotely. */
export type RemoteHistory = { readonly [E in EntityName]: Query<Records[E], Records[E], "records", "async"> };

/**
 * An in-memory history over turn records you hold (canonical camelCase, as `GET …/ledger` and
 * `…/query` return them), for team `team`. `history` is exactly what programs get as HISTORY (read-only);
 * `turns` is the same query; append() adds new turns, keeping the indexes up to date.
 */
export class Local {
  readonly #table: Table<Records[ProgramEntity]>;
  readonly history: ProgramHistory;
  readonly team: number | null;
  constructor(records: readonly unknown[] = [], team: number | null = null) {
    this.#table = new Table(PROGRAM_ENTITY, records);
    this.team = team;
    this.history = Object.freeze({ [PROGRAM_ENTITY]: this.#table.query(team) }) as ProgramHistory;
    Object.freeze(this);
  }
  get turns(): ProgramHistory[ProgramEntity] { return this.history[PROGRAM_ENTITY]; }
  get size(): number { return this.#table.size; }
  append(records: readonly unknown[]): void { this.#table.append(records); }
}

export function local(records: readonly unknown[] = [], team: number | null = null): Local {
  return new Local(records, team);
}

export interface ConnectOptions {
  /** The server, e.g. "http://localhost:3000" ("" for the page's own origin). */
  readonly base?: string;
  readonly room: string;
  /** A game's short id; leave it out to query the room's finished games. */
  readonly game?: string | null;
  /** A session token, sent as `Authorization: Bearer`. */
  readonly token?: string | null;
  /** Replaces the built-in POST: post(path, ast) → { rows, truncated }. */
  readonly post?: (path: string, ast: Ast) => Promise<Page>;
}

/** Every entity of a game (or of a room's finished games), queried over HTTP. */
export function connect(options: ConnectOptions): RemoteHistory {
  const path = `/api/rooms/${encodeURIComponent(options.room)}${options.game ? `/games/${encodeURIComponent(options.game)}` : ""}/query`;
  const post = options.post ?? (async (p: string, ast: Ast): Promise<Page> => {
    const res = await fetch((options.base ?? "") + p, {
      method: "POST",
      headers: { "content-type": "application/json", ...(options.token ? { authorization: `Bearer ${options.token}` } : {}) },
      body: JSON.stringify(ast),
    });
    const body = await res.json().catch(() => ({}));
    if (!res.ok) throw new QueryError(body.error ?? `HTTP ${res.status}`);
    return body as Page;
  });
  const runner: Runner<"async"> = { run: async (ast: Ast) => deepFreeze([...(await post(path, validate(ast))).rows]) };
  const root: Record<string, unknown> = {};
  for (const e of Object.keys(SCHEMA.entities)) root[e] = new Query({ from: e as EntityName }, runner);
  return Object.freeze(root) as RemoteHistory;
}
